/* Original Observatory: an illustrative process, never fabricated live research. */
(()=>{
 const original=window.REIDreamHome;
 window.REIDreamHome=()=>original().replace('<section class="dream-manifesto"',`${story()}<section class="dream-manifesto"`);
 function story(){return `<section class="observatory-story" id="observatory" aria-labelledby="observatory-title"><div class="observatory-sticky"><div class="observatory-top"><span>REI / THE OBSERVATORY</span><button type="button" data-observe-skip>Skip the exploration <span aria-hidden="true">↘</span></button></div><div class="observatory-composition"><div class="observatory-copy"><p class="eyebrow">A QUESTION, TAKING SHAPE</p><h2 id="observatory-title" aria-label="Follow the invisible thread.">Follow <br>the <em>invisible</em><br>thread.</h2><p class="observatory-lead">From a spark of curiosity to something you can stand behind. Four moves. One connected process.</p><div class="observatory-chapters" role="tablist" aria-label="Research story chapters">${['Question','Sources','Evidence','Argument'].map((x,i)=>`<button type="button" role="tab" id="observe-tab-${i}" aria-controls="observe-panel" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-observe-stage="${i}"><span>0${i+1}</span><b>${x}</b><i aria-hidden="true">↗</i></button>`).join('')}</div></div><div class="observatory-visual"><div class="observatory-model" aria-hidden="true"><div class="observatory-fallback"><i></i><i></i><span>?</span></div><canvas></canvas></div><div class="observatory-crosshair" aria-hidden="true">+</div><div class="observatory-model-note"><span>OPTICAL ARCHIVE / <b id="observe-model-number">01</b></span><span>ILLUSTRATIVE STUDY</span></div><div class="observatory-caption" id="observe-panel" role="tabpanel" aria-labelledby="observe-tab-0" tabindex="0"><span class="eyebrow" id="observe-label">01 / DEFINE</span><h3 id="observe-heading">A good question changes what you see.</h3><p id="observe-description">Turn a broad interest into a question with a clear subject, context, and purpose.</p><a id="observe-link" href="#lesson/0">Find your starting point <span aria-hidden="true">↗</span></a></div></div></div><div class="observatory-bottom"><span>SCROLL TO FOLLOW / SELECT TO EXPLORE</span><div class="observatory-meter" aria-hidden="true"><i></i></div><span id="observe-count">01 — 04</span></div></div></section>`}
})();
